	@Test
	void callerFrameNamesCannotBeCanonicalizedAsDeadBindAliases() {
		Projection first = callerAliasProjection("callerA");
		Projection second = callerAliasProjection("callerB");
		QueryBindingSet invocation = new QueryBindingSet();
		invocation.addBinding("callerA", G1);
		assertThat(rows(first, invocation)).containsExactly(EmptyBindingSet.getInstance());
		assertThat(rows(second, invocation)).isEmpty();
		PackedQueryCacheIdentity firstIdentity = PackedQueryCacheIdentity.createComplete(first);
		PackedQueryCacheIdentity secondIdentity = PackedQueryCacheIdentity.createComplete(second);
		assertThat(firstIdentity).isNotNull();
		assertThat(secondIdentity).isNotNull();
		assertThat(firstIdentity.matches(secondIdentity)).isFalse();
		PackedQueryFamilyIdentity firstFamily = PackedQueryFamilyIdentity.create(first, null);
		PackedQueryFamilyIdentity secondFamily = PackedQueryFamilyIdentity.create(second, null);
		assertThat(firstFamily).isNotNull();
		assertThat(secondFamily).isNotNull();
		assertThat(firstFamily.matches(secondFamily)).isFalse();
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedPlanningResult one = PackedCascadesPlanner.optimize(first.clone(), OptimizationGoal.root(), cache,
				CACHE_CONTEXT, COSTS);
		PackedPlanningResult two = PackedCascadesPlanner.optimize(second.clone(), OptimizationGoal.root(), cache,
				CACHE_CONTEXT, COSTS);
		assertThat(one.metrics().groups()).isPositive();
		assertThat(two.metrics().groups()).isPositive();
		assertThat(two.metrics().planCacheHit()).isFalse();
		assertThat(rows(one.selectedPlan(), invocation)).containsExactly(EmptyBindingSet.getInstance());
		assertThat(rows(two.selectedPlan(), invocation)).isEmpty();
	}

	private static Projection callerAliasProjection(String callerName) {
		Projection projection = projection(PRIVATE, Var.of(callerName));
		Filter guard = (Filter) projection.getArg();
		guard.setArg(new Extension(new SingletonSet(), new ExtensionElem(new ValueConstant(G2), callerName)));
		return projection;
	}

	private static Projection orderedProjection(String parameter) {
		Projection projection = new Projection(new Order(ranks(), new OrderElem(orderKey())),
				new ProjectionElemList(new ProjectionElem("rank")), true);
		projection.setProjectionContext(Var.of(CALLER));
		projection.setInheritedGraphParameter(parameter);
		return projection;
	}

	private static ValueExpr orderKey() {
		return new If(new Bound(Var.of(PRIVATE)), Var.of("rank"),
				new MathExpr(new ValueConstant(VF.createLiteral(0)), Var.of("rank"), MathExpr.MathOp.MINUS));
	}

	private static BindingSetAssignment ranks() {
		BindingSetAssignment ranks = new BindingSetAssignment();
		ranks.setBindingSets(List.of(rank(2), rank(1)));
		return ranks;
	}

	private static QueryBindingSet rank(int value) {
		QueryBindingSet row = new QueryBindingSet();
		row.addBinding("rank", VF.createLiteral(value));
		return row;
	}

	private static void assertSelectedAndCachedRows(TupleExpr source, BindingSet input, List<BindingSet> expected) {
		PackedPlanningResult selected = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(), COSTS);
		assertThat(selected.metrics().groups()).isPositive();
		assertThat(selected.metrics().winners()).isPositive();
		assertThat(rows(selected.selectedPlan(), input)).containsExactlyInAnyOrderElementsOf(expected);
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedPlanningResult cold = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(), cache,
				CACHE_CONTEXT, COSTS);
		PackedPlanningResult warm = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(), cache,
				CACHE_CONTEXT, COSTS);
		assertThat(cold.metrics().planCacheHit()).isFalse();
		assertThat(warm.metrics().planCacheHit()).isTrue();
		assertThat(rows(cold.selectedPlan(), input)).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(rows(warm.selectedPlan(), input)).containsExactlyInAnyOrderElementsOf(expected);
	}

	private static Projection projection(String parameter, Var caller) {
		Filter guard = new Filter(new SingletonSet(), new SameTerm(Var.of(PRIVATE), new ValueConstant(G1)));
		guard.setConditionBindingScope(ConditionBindingScope.ALL);
		Projection projection = new Projection(guard, new ProjectionElemList(), true);
		projection.setProjectionContext(caller);
		projection.setInheritedGraphParameter(parameter);
		return projection;
	}

	private static QueryBindingSet input(IRI graph) {
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding(CALLER, graph);
		return input;
	}

	private static List<BindingSet> rows(TupleExpr expression, BindingSet input) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<BindingSet> result = new ArrayList<>();
		try (var rows = strategy.precompile(expression.clone(), new QueryEvaluationContext.Minimal(null))
				.evaluate(input)) {
			while (rows.hasNext()) {
				result.add(new QueryBindingSet(rows.next()));
			}
		}
		return result;
	}
